  builder.onLoad({filter:/\.mjs$/,namespace:'file'},async({path:file})=>{
   const row=await snapshot(file);
   return{contents:row.selected.toString('utf8'),loader:'js',resolveDir:path.dirname(file)};
  });
 }}]});
}finally{api.stop();}
assert.equal(build.outputFiles.length,1);
for(const output of Object.values(build.metafile.outputs))assert.equal(output.imports.length,0,'external output imports');
for(const name of Object.keys(build.metafile.inputs))assert(snapshots.has(name),'uncaptured actual input: '+name);
assert.equal(Object.keys(build.metafile.inputs).length,snapshots.size);
const participation={};
for(const name of Object.keys(input.overrides)){
 assert(Object.hasOwn(build.metafile.inputs,name),'candidate module not bundled: '+name);
 const includedBytes=Object.values(build.metafile.outputs).reduce((sum,o)=>sum+(o.inputs[name]?.bytesInOutput||0),0);
 assert(includedBytes>0,'candidate module was fully removed: '+name);
