 participation[name]={sha256:sha(row.selected),gitBlob:blob(row.selected),bytesInOutput:includedBytes,physicalSHA256:sha(row.physical),sourceDiffersFromPhysical:!row.physical.equals(row.selected)};
}
const output=build.outputFiles[0],outputBytes=output.contents.byteLength,outputSHA256=sha(output.contents);
const sources=[];
for(const[name,row]of snapshots){
 assert(row.physical.equals(await fsp.readFile(row.absolute)),'physical source changed: '+name);
 assert.equal(blob(row.selected),input.expected[name]);
 sources.push({path:name,bytes:row.selected.length,sha256:sha(row.selected),gitBlob:blob(row.selected),physicalBytes:row.physical.length,physicalSHA256:sha(row.physical),overrideSupplied:Object.hasOwn(input.overrides,name),sourceDiffersFromPhysical:!row.physical.equals(row.selected)});
