sources.sort((a,b)=>a.path.localeCompare(b.path));
assert.equal(sha(await fsp.readFile(input.esbuildModule)),input.esbuildModuleSHA256);
assert.equal(blob(await fsp.readFile(path.join(root,input.maintainedBuilder.path))),input.maintainedBuilder.gitBlob);
