const evalIndex=process.execArgv.indexOf('-e');
const receipt={kind:'native-combined-application-compilation-only',node:process.version,started,finished:new Date().toISOString(),runnerSHA256:sha(process.execArgv[evalIndex+1]),declaredCompositionCommit:input.compositionCommit,declaredCompositionTree:input.compositionTree,actualCheckoutHead,actualCheckoutStatusSHA256:sha(beforeStatus),sourceMeaning:'Exact compiled bytes checked against the complete pinned Git tree. Actual local checkout identity is preserved; immutable in-memory source selection is disclosed separately.',tool:{name:'esbuild',version:api.version,moduleSHA256:input.esbuildModuleSHA256},maintainedBuilder:{...input.maintainedBuilder,sha256:sha(maintainedBuilderBytes)},options:{...options,absWorkingDir:'[verified local checkout]'},snapshotPlugin:'Maintained exact-source-snapshot approach with explicit pinned source selection; physical originals independently rechecked.',inputCount:sources.length,inputManifestSHA256:sha(JSON.stringify(sources)),sources,participation,output:{files:1,bytes:outputBytes,sha256:outputSHA256,imports:0,handling:'Compiled bytes remained in native process memory, were not saved or emitted, and were discarded after metadata capture.'},warnings,checks:{allCompiledInputsMatchPinnedCombinedTree:true,bothCandidateModulesContributeOutput:true,oneOutput:true,noOutputImports:true,allActualInputsCaptured:true,allPhysicalSourcesUnchanged:true,toolAndMaintainedBuilderUnchanged:true,gitStatusUnchanged:true},limits:'Compilation-only through the supported esbuild API. No maintained HTML assembly, embedded-asset/license receiving, manifest publication/readback, clean combined checkout, filesystem provenance test, browser execution, final compiled artifact or delivery claim.'};
